      "proposed_laureates": [
        "Alexandre Blais",
        "Robert J. Schoelkopf",
        "Steven M. Girvin"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made strong, controllable coupling between microwave photons and individual superconducting artificial atoms a practical experimental regime. It established a central platform for quantum optics and quantum information.",
        "attribution": "Blais's theory and the Yale experimental program associated with Schoelkopf and Girvin form a compelling theory-experiment attribution, though the wider circuit-QED community contributed substantially.",
        "maturity": "The result has been extensively reproduced and developed across laboratories, with lasting influence on quantum optics and superconducting quantum processors.",
        "uncertainties": [
          "The boundary between this foundational physical discovery and later engineering advances in superconducting quantum computing is not sharp."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical-lattice experiments made strongly correlated many-body systems controllable and measurable, opening a powerful route to quantum simulation of condensed-matter physics.",
        "attribution": "Zoller's theoretical program and landmark experimental work by Bloch and Greiner are prominent contributions; the field's rapid growth makes any short laureate list incomplete.",
        "maturity": "The experimental capabilities and key phenomena have been robustly reproduced, and the platform has continued to yield important results.",
        "uncertainties": [
          "The broad achievement spans multiple experiments and groups, complicating a clean definition of the prizeworthy discovery and its attribution."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B051",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction and fault-tolerant computation showed how quantum information can in principle be protected against noise, supplying a foundational framework for quantum computing.",
        "attribution": "Shor and Steane independently established key error-correction ideas, while Kitaev's topological codes and fault-tolerance work provided a distinct, influential development.",
        "maturity": "The theory is mature and experimentally testable; demonstrations of increasingly capable error correction support its physical relevance, though universal fault-tolerant computing remains unrealized.",
        "uncertainties": [
          "The proposed discovery groups several related theoretical advances whose boundaries and relative weights require careful judgment."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Gerard 't Hooft",
        "Juan Maldacena",
        "Leonard Susskind"
      ],
      "assessment": {
        "nobel_worthiness": "The holographic principle and AdS/CFT duality transformed thinking about quantum gravity and strongly coupled quantum field theories, with unusually broad theoretical influence.",
        "attribution": "The credited names represent the principle's early development and its concrete realization, although the conceptual lineage is distributed across several foundational works.",
        "maturity": "The mathematical framework has been deeply developed and applied, but its direct connection to the observed universe and experimentally testable quantum gravity remains uncertain.",
        "uncertainties": [
          "The duality is established in specific theoretical settings, while its physical applicability beyond them remains unresolved."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mark Saffman",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Programmable neutral-atom arrays with Rydberg interactions brought large, flexible quantum simulators and processors within reach, enabling controlled studies of many-body dynamics.",
        "attribution": "The named researchers represent influential experimental and theoretical programs, but the advance was built by several groups and the credit boundary is difficult to draw.",
        "maturity": "The platform has progressed rapidly and key capabilities are reproduced across laboratories; its long-term scientific reach is still unfolding.",
        "uncertainties": [
          "The prize case may depend on whether the lasting achievement is the platform itself or the discoveries it enables."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction and observation of time-reversal-invariant topological insulators and the quantum spin Hall effect established a major new class of quantum matter.",
        "attribution": "Kane and Mele supplied the influential theory, and Molenkamp's experiments provided an important demonstration of the quantum spin Hall state.",
        "maturity": "The underlying topological framework is robust, though early material realizations had limitations and the experimental signatures are sensitive to sample conditions.",
        "uncertainties": [
          "The first experimental realization was not an ideal insulator, leaving some ambiguity about how to weigh prediction against demonstration."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Kenneth J. Schafer",
        "Maciej Lewenstein",
        "Paul B. Corkum"
      ],
      "assessment": {
        "nobel_worthiness": "The recollision model gave a clear physical picture of strong-field high-harmonic generation and helped establish attosecond science as a field for probing electron motion.",
        "attribution": "Corkum's three-step model and the complementary theory by Schafer and Lewenstein are central contributions, while the subsequent field involved many experimental advances.",
        "maturity": "The model is broadly confirmed and the methods have become powerful tools, with extensive experimental development over decades.",
        "uncertainties": [
          "The discovery is a theoretical framework for a field rather than a single sharply bounded experimental event."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B064",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks brought atomic timekeeping to unprecedented precision and enabled tests of fundamental physics with remarkable sensitivity.",
        "attribution": "Katori and Ye independently led complementary approaches that were both essential to the field's development.",
        "maturity": "The precision has been demonstrated and improved across laboratories, with clocks now supporting demanding measurement and metrology applications.",
        "uncertainties": [
          "It is difficult to distinguish the foundational clock concepts from the cumulative technical improvements that reached the stated precision."
        ]
      }
    }
  ]
